-- Generated by tools/build_action_data.py; do not edit.
return {["scripts/actions/spells/trust/aahm.lua"]={["Path"]="scripts/actions/spells/trust/aahm.lua",["SHA256"]="a4ace70078c9ab440685eb970bb800ed7efa350691d1c3932fd959cecb202c06",["Text"]="-----------------------------------\n-- Trust: AAHM\n-- Possesses HP+20%\n-- Possesses an Utsusemi +1 trait which grants AA HM an extra shadow.\n-- If there is a Tank in the party, behaves as a damage dealer: Uses Innin, Berserk.\n-- If there are no other tanks in the party, behaves as a tank: Uses Yonin, Warcry.\n-- Uses Provoke in both situations in order to be sub tank.\n-- Casts debuffs when does not have hate.\n-- Uses weapon skills at 1000 TP and does not try to skillchain.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:addMobMod(xi.mobMod.CAN_PARRY, 3)\n\n    mob:addMod(xi.mod.UTSUSEMI_BONUS, 1)\n    mob:addMod(xi.mod.FASTCAST, 30)\n    mob:addMod(xi.mod.ENMITY, 15)\n    mob:addMod(xi.mod.DUAL_WIELD, 10)\n    mob:addMod(xi.mod.DMG, -500) -- Damage Taken -5%\n    mob:addMod(xi.mod.HPP, 20)\n\n    local lvl = mob:getMainLvl()\n    local lastSynergyBonus = 0\n\n    -- Dynamic modifier that checks party member list on tick to apply\n    mob:addListener('COMBAT_TICK', 'AAHM_CTICK', function(mobArg)\n        local synergyMembers =\n        {\n            xi.magic.spell.AAEV,\n            xi.magic.spell.AAMR,\n            xi.magic.spell.AATT,\n            xi.magic.spell.AAGK\n        }\n\n        local synergyCount = 0\n        local party = mobArg:getMaster():getPartyWithTrusts()\n\n        for _, member in pairs(party) do\n            if member:getObjType() == xi.objType.TRUST then\n                local trustId = member:getTrustID()\n                for _, sId in ipairs(synergyMembers) do\n                    if trustId == sId then\n                        synergyCount = synergyCount + 1\n                        break\n                    end\n                end\n            end\n        end\n\n        -- Determine what the bonus should be\n        local targetBonus = (synergyCount == #synergyMembers) and 50 or 0\n        -- Only update if the state has changed\n        if targetBonus ~= lastSynergyBonus then\n            -- Subtract exactly what we added last time\n            mobArg:delMod(xi.mod.MEVA, lastSynergyBonus)\n            -- Add the new bonus\n            mobArg:addMod(xi.mod.MEVA, targetBonus)\n            -- Update lastSynergyBonus\n            lastSynergyBonus = targetBonus\n        end\n    end)\n\n    if lvl >= 10 then\n        mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\n    end\n\n    if lvl >= 30 then\n        mob:addGambit(ai.t.SELF, { { ai.c.NOT_PT_HAS_TANK, 0 }, { ai.c.NOT_STATUS, xi.effect.BERSERK } }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.BERSERK })\n    end\n\n    if lvl >= 40 then\n        mob:addGambit(ai.t.SELF, { { ai.c.NOT_PT_HAS_TANK, 0 }, { ai.c.NOT_STATUS, xi.effect.INNIN } }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.INNIN })\n        mob:addGambit(ai.t.SELF, { { ai.c.PT_HAS_TANK,     0 }, { ai.c.NOT_STATUS, xi.effect.YONIN } }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.YONIN })\n    end\n\n    if lvl >= 70 then\n        mob:addGambit(ai.t.SELF, { { ai.c.PT_HAS_TANK, 0 }, { ai.c.NOT_STATUS, xi.effect.WARCRY } }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.WARCRY })\n    end\n\n    mob:addGambit(ai.t.SELF,    { ai.c.NOT_STATUS,         xi.effect.MIGAWARI   }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.MIGAWARI_ICHI  })\n    mob:addGambit(ai.t.SELF,    { ai.c.NOT_STATUS,         xi.effect.COPY_IMAGE }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.UTSUSEMI })\n    mob:addGambit(ai.t.TARGET,  { ai.c.NOT_HAS_TOP_ENMITY, 0                    }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.HOJO     }, 30)\n    mob:addGambit(ai.t.TARGET,  { ai.c.NOT_HAS_TOP_ENMITY, 0                    }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.KURAYAMI }, 30)\n\n    mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM)\n\n    mob:addListener('WEAPONSKILL_USE', 'AAHM_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action)\n        if skill:getID() == xi.mobSkill.CROSS_REAVER_3 then\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1) -- Apathy strikes!\n        end\n    end)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/aamr.lua"]={["Path"]="scripts/actions/spells/trust/aamr.lua",["SHA256"]="ea3d09cdee98ea9fbb6d5157a3d39f3a971288e60ba146afc0aace0c2e219157",["Text"]="-----------------------------------\n-- Trust: AAMR\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/aatt.lua"]={["Path"]="scripts/actions/spells/trust/aatt.lua",["SHA256"]="124f555cba65da74aaa1e7be28a718d350c644c0fb814f2162a5a6163ee59757",["Text"]="-----------------------------------\n-- Trust: AATT\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/abenzio.lua"]={["Path"]="scripts/actions/spells/trust/abenzio.lua",["SHA256"]="bf7162088c8597d76aca3edf581589ffbcb4e2d2d468c33e6f5f15f878525290",["Text"]="-----------------------------------\n-- Trust: Abenzio\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nlocal isWearingMandragoraGear = function(player)\n    local wearingHead = player:getEquipID(xi.slot.HEAD) == 26705 or player:getEquipID(xi.slot.HEAD) == 26706 -- Mandragora Masque or Masque + 1\n    local wearingBody = player:getEquipID(xi.slot.BODY) == 27854 or player:getEquipID(xi.slot.BODY) == 27855 -- Mandragora Suit or Suit + 1\n    return wearingHead and wearingBody\nend\n\nspellObject.onMobSpawn = function(mob)\n    local master = mob:getMaster()\n    if isWearingMandragoraGear(master) then\n        xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n    end\nend\n\nspellObject.onMobDespawn = function(mob)\n    local master = mob:getMaster()\n    if isWearingMandragoraGear(master) then\n        xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\n    end\nend\n\nspellObject.onMobDeath = function(mob)\n    local master = mob:getMaster()\n    if isWearingMandragoraGear(master) then\n        xi.trust.message(mob, xi.trust.messageOffset.DEATH)\n    end\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/abquhbah.lua"]={["Path"]="scripts/actions/spells/trust/abquhbah.lua",["SHA256"]="d628aa18b619eb84f8021ecd7508b3271b36a67281d362558517ceb487a7f291",["Text"]="-----------------------------------\n-- Trust: Abquhbah\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_SC_AVAILABLE, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.BERSERK })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_SC_AVAILABLE, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.WARCRY })\n    mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.RESTRAINT })\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.RANDOM, 1500)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/adelheid.lua"]={["Path"]="scripts/actions/spells/trust/adelheid.lua",["SHA256"]="12f00a8bdb5d8df151dc66b228ec7072a7069c3d361344b9bafcb1e84dc4dc58",["Text"]="-----------------------------------\n-- Trust: Adelheid\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    -- Records of Eminence: Alter Ego: Adelheid\n    if caster:getEminenceProgress(936) then\n        xi.roe.onRecordTrigger(caster, 936)\n    end\n\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.ADDENDUM_BLACK }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.DARK_ARTS })\n    -- TODO: Restrict Addendum Black to Level 30+\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.ADDENDUM_BLACK }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.ADDENDUM_BLACK })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_WS, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_MS, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_JA, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n    mob:addGambit(ai.t.TARGET, { ai.c.CASTING_MA, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n\n    -- TODO: Choose Storms based on Mob Weakness before falling back to matching day\n    mob:addGambit(ai.t.SELF, { ai.c.NO_STORM, 0 }, { ai.r.MA, ai.s.STORM_DAY, 0 }, 0)\n\n    -- TODO: Choose Helix based on Mob Weakness before falling back to matching day\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.HELIX }, { ai.r.MA, ai.s.HELIX_DAY, 0 }, 0)\n\n    mob:addGambit(ai.t.TANK, { ai.c.HPP_LT, 50 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 33 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    -- TODO: Add Magic Burst Logic to Gambits to MB with Helix corresponding to SC\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_SC_AVAILABLE, 0 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.NONE }, 75)\n\n    mob:addListener('WEAPONSKILL_USE', 'ADELHEID_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == xi.mobSkill.TWIRLING_DERVISH then\n            if math.randomInt(1, 100) <= 33 then\n                xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1) -- You may want to cover your ears!\n            end\n        end\n    end)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ajido-marujido.lua"]={["Path"]="scripts/actions/spells/trust/ajido-marujido.lua",["SHA256"]="9357ab9874673e2082fb8f1408bd8c66f06708c820f272b02d621d48ba65ccac",["Text"]="-----------------------------------\n-- Trust: Ajido-Marujido\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.SHANTOTTO] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.STAR_SIBYL] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.KORU_MORU] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.KARAHA_BARUHA] = xi.trust.messageOffset.TEAMWORK_4,\n        [xi.magic.spell.SEMIH_LAFIHNA] = xi.trust.messageOffset.TEAMWORK_5,\n    })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.MB_AVAILABLE, 0 }, { ai.r.MA, ai.s.MB_ELEMENT, xi.magic.spellFamily.NONE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 25 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.SLOW }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SLOW }, 60)\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_SC_AVAILABLE, 0 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.NONE }, 60)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NO_MOVE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/aldo.lua"]={["Path"]="scripts/actions/spells/trust/aldo.lua",["SHA256"]="92c1808970d6edba05d3b37cc23dfb9babd1b7436906047f4d5906f0af0fb2d4",["Text"]="-----------------------------------\n-- Trust: Aldo\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.ALDO_UC)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/aldo_uc.lua"]={["Path"]="scripts/actions/spells/trust/aldo_uc.lua",["SHA256"]="29af63c5ca6a30d7fe2cf8496afc953baa795e46c08293cfc2ec37031db34b4a",["Text"]="-----------------------------------\n-- Trust: Aldo UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.ALDO)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/amchuchu.lua"]={["Path"]="scripts/actions/spells/trust/amchuchu.lua",["SHA256"]="c50c8f27377a7dd0ec78648669b9fe5a16cba7ad9ccdcac09a26683a9bdcecc1",["Text"]="-----------------------------------\n-- Trust: Amchuchu\n-- Possesses Inspiration (50% Fast Cast effect during Vallation, is party-wide during Valiance), Converts 5% of Physical Damage Taken to MP.\n-- Only casts enhancing spells on herself.\n-- Uses Embolden when casting Protect.\n-- She can rapidly generate Volatile Enmity for initial threat or recovery from enmity reset attacks with a cornucopia of abilties and spells like Provoke, Flash, and Foil.\n-- Uses Runes resisting the element of the current day. After taking magic damage, uses the appropriate Bar-spell and changes runes.\n-- Uses One for All in response to enemies casting high-tier damaging spells.\n-- Magic Bursts Level 4 Light or Level 4 Darkness skillchains using Lunge.\n-- Holds up to 3000 TP to close skillchains. Weapon skills are a lower priority,\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:addMobMod(xi.mobMod.CAN_PARRY, 3)\n\n    mob:addMod(xi.mod.INSPIRATION_FAST_CAST, 50)\n    mob:addMod(xi.mod.ENMITY, 15)\n    mob:addMod(xi.mod.DMG, -500) -- Damage Taken -5%\n    mob:addMod(xi.mod.HPP, 10)\n    mob:addMod(xi.mod.MPP, 10)\n\n    local lvl = mob:getMainLvl()\n\n    if lvl >= 5 then\n        mob:addGambit(ai.t.SELF, { ai.c.NO_MAX_RUNE, 0 }, { ai.r.JA, ai.s.RUNE_DAY, xi.ja.IGNIS })\n    end\n\n    if lvl >= 10 then\n        mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS,           0                    }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE   })\n        mob:addGambit(ai.t.TARGET, { ai.c.CAST_ELE_MA_SELF, xi.effect.VALLATION  }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VALLATION })\n    end\n\n    if lvl >= 20 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SWORDPLAY }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SWORDPLAY })\n    end\n\n    if lvl >= 25 then\n        mob:addGambit(ai.t.TARGET, { ai.c.LUNGE_MB_AVAILABLE, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.LUNGE })\n        mob:addGambit(ai.t.TARGET, { ai.c.LUNGE_MB_AVAILABLE, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SWIPE })\n    end\n\n    if lvl >= 30 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.BERSERK }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.BERSERK })\n    end\n\n    if lvl >= 50 then\n        mob:addGambit(ai.t.TARGET, { ai.c.CASTING_ELE_MA_AOE, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VALIANCE })\n    end\n\n    if lvl >= 60 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.EMBOLDEN }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.EMBOLDEN })\n    end\n\n    if lvl >= 65 then\n        mob:addGambit(ai.t.SELF, { ai.c.HPP_LT, 50 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VIVACIOUS_PULSE })\n    end\n\n    if lvl >= 75 then\n        mob:addGambit(ai.t.SELF, { ai.c.HPP_LT, 75 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.BATTUTA })\n    end\n\n    if lvl >= 95 then\n        mob:addGambit(ai.t.TARGET, { ai.c.CASTING_ELE_MA_AOE, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.ONE_FOR_ALL })\n    end\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.FLASH   }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FLASH         })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.PHALANX }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PHALANX       })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.FOIL    }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FOIL          })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.PROTECT })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.SHELL   }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.SHELL   })\n\n    mob:addGambit(ai.t.TARGET, { { ai.c.CAST_ELE_MA_SELF, 0                   }, { ai.c.NEED_ELE_BAREFFECT,  0 }, }, { ai.r.MA, ai.s.DEF_BAR_ELEMENT, 0                          })\n    mob:addGambit(ai.t.SELF,   { { ai.c.NOT_STATUS,       xi.effect.REGEN     }, { ai.c.HPP_LT,             75 }, }, { ai.r.MA, ai.s.HIGHEST,         xi.magic.spellFamily.REGEN })\n    mob:addGambit(ai.t.SELF,   { { ai.c.NOT_STATUS,       xi.effect.REFRESH   }, { ai.c.MPP_LT,             75 }, }, { ai.r.MA, ai.s.SPECIFIC,        xi.magic.spell.REFRESH     })\n\n    mob:addGambit(ai.t.SELF, {\n        { ai.c.NOT_STATUS, xi.effect.STONESKIN },\n        { ai.c.HPP_LT, 75 },\n        { ai.c.MPP_GTE, 50 }, }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONESKIN })\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.HIGHEST, 3000)\n\n    mob:addListener('WEAPONSKILL_USE', 'AMCHUCHU_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action)\n        if skill:getID() == xi.mobSkill.DIMIDIATION_1 then\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1) -- Nothing-wothing wrong with a little mad science now and again!\n        end\n    end)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/apururu_uc.lua"]={["Path"]="scripts/actions/spells/trust/apururu_uc.lua",["SHA256"]="7ee6b2bbc4b1b8bb586ecbf0db9796873cbf620bca9ea74e446cd1216425a651",["Text"]="-----------------------------------\n-- Trust: Apururu UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nlocal isWearingApururuShirt = function(player)\n    local wearingBody = player:getEquipID(xi.slot.BODY) == xi.item.APURURU_UNITY_SHIRT\n    return wearingBody\nend\n\nspellObject.onMobSpawn = function(mob)\n    local master = mob:getMaster()\n    if isWearingApururuShirt(master) then\n        xi.trust.message(mob, xi.trust.messageOffset.TEAMWORK_2)\n    else\n        xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n    end\n\n    -- Unity ranking high : xi.trust.message(mob, xi.trust.messageOffset.TEAMWORK_1)\n\n    -- TODO: UC trusts are supposed to get bonuses depending on unity ranking. Needs research.\n    -- TODO: Custom spawn messages if Unity ranking is higher.\n    -- TODO: Setup conditional behaviors for Devotion, Martyr\n\n    mob:addGambit(ai.t.SELF, { { ai.c.MPP_LT, 51 }, { ai.c.LVL_GTE, 50 }, { ai.c.TP_GTE, 1000 } }, { ai.r.MS, ai.s.SPECIFIC, xi.mobSkill.NOTT })\n\n    mob:addGambit(ai.t.SELF, { ai.c.MPP_LT, 25 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.CONVERT })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 25 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURAGA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURAGA })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECTRA })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.SHELL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SHELLRA })\n\n    mob:addGambit(ai.t.MELEE, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.HASTE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.POISON }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.POISONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PARALYNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.BLINDNESS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.BLINDNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PETRIFICATION }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.DISEASE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.VIRUNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.CURSE_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n\n    mob:addGambit(ai.t.SELF, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.STONESKIN }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONESKIN })\n\n    -- BGwiki states 75/tick regain.  Only used for Nott WS.\n    mob:addMod(xi.mod.REGAIN, 75)\n\n    mob:setAutoAttackEnabled(false)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.MID_RANGE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/arciela.lua"]={["Path"]="scripts/actions/spells/trust/arciela.lua",["SHA256"]="bf1dc59b3dc9c11dd57d887b1bc48d9c8285d07f2c9a3e751c5051fc2ef82131",["Text"]="-----------------------------------\n-- Trust: Arciela\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.ARCIELA_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/arciela_ii.lua"]={["Path"]="scripts/actions/spells/trust/arciela_ii.lua",["SHA256"]="410c0dd07ca51cb8f21af7688de37bdd38545ad794a19e90c99f21ca99e59e34",["Text"]="-----------------------------------\n-- Trust: Arciela II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.ARCIELA)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/areuhat.lua"]={["Path"]="scripts/actions/spells/trust/areuhat.lua",["SHA256"]="db8953cb728195ec83d4ffb2fe20a45e4a30960ad1d535f754d76c0e51392fcf",["Text"]="-----------------------------------\n-- Trust: Areuhat\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.AGGRESSOR }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.AGGRESSOR })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.BERSERK }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.BERSERK })\n    mob:addGambit(ai.t.PARTY, { ai.l.OR(\n                        { ai.c.NOT_STATUS, xi.effect.WARCRY },\n                        { ai.c.NOT_STATUS, xi.effect.BLOOD_RAGE })\n                            }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.BLOOD_RAGE })\n\n    mob:addListener('WEAPONSKILL_USE', 'AREUHAT_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == xi.mobSkill.DRAGON_BREATH_3 then\n            if math.randomInt(1, 100) <= 33 then\n                xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1) -- Perhaps I should just burn the eyes of these infidels with my true form.\n            end\n        end\n    end)\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.HIGHEST, 2000)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/august.lua"]={["Path"]="scripts/actions/spells/trust/august.lua",["SHA256"]="a8f6c15cbb5a6b790bbdf332730db6b55029e1eda6e00bb782d660e9d1b6013f",["Text"]="-----------------------------------\n-- Trust: August\n-- Possesses HP+10%\n-- Uses Divine Emblem to enhance Holy II.\n-- August's attacks are not affected by Sambas.\n-- August wears the Founder's Gear and has accordingly all Killer Effects and high resistance to Terror.\n-- August can switch weapons at will while auto attacking and performing weapon skills, it is unknown if this changes his damage type or is merely cosmetic.\n-- August is considered to be wielding a Great Sword for the purposes of Damage Limit+ and Inundation.\n-- Uses weapon skills at 1000 TP and does not try to skillchain.\n-- Daybreak (~3 min cooldown, ~1 min 30 sec duration)\n-- When August's HP drops below a certain threshold (~66%), he uses Daybreak if it's available which partially restores some HP and MP, resets his TP, and activates an aura with wings of light\n-- Daybreak is a -50% PDT effect, full Erase, Stats boost, Regen, and Store TP\n-- During Daybreak, August's next weapon skill will be Fulminous Fury or Noble Frenzy, followed by No Quarter\n-- Daybreak is removed after the use of No Quarter.\n-- Daybreak's cooldown starts when No Quarter is used.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.ARCIELA]   = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.TEODOR]    = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.ROSULATIA] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.MORIMAR]   = xi.trust.messageOffset.TEAMWORK_4,\n    })\n\n    mob:setMobMod(xi.mobMod.CAN_SHIELD_BLOCK, 1)\n    mob:setMobMod(xi.mobMod.CAN_PARRY, 3)\n\n    local killerEffects =\n    {\n        xi.mod.VERMIN_KILLER,\n        xi.mod.BIRD_KILLER,\n        xi.mod.AMORPH_KILLER,\n        xi.mod.LIZARD_KILLER,\n        xi.mod.AQUAN_KILLER,\n        xi.mod.PLANTOID_KILLER,\n        xi.mod.BEAST_KILLER,\n        xi.mod.UNDEAD_KILLER,\n        xi.mod.ARCANA_KILLER,\n        xi.mod.DRAGON_KILLER,\n        xi.mod.DEMON_KILLER,\n        xi.mod.EMPTY_KILLER,\n        -- xi.mod.HUMANOID_KILLER, -- This can be uncommented once https://github.com/LandSandBoat/server/issues/7610 has been fixed\n        xi.mod.LUMINIAN_KILLER,\n        xi.mod.LUMINION_KILLER,\n    }\n\n    for i = 1, #killerEffects do\n        mob:addMod(killerEffects[i], 8) -- this is what you would get using all the Founders Gear set\n    end\n\n    local lvl = mob:getMainLvl()\n    local shieldMasteryPower = 0\n\n    if lvl >= 96 then\n        shieldMasteryPower = 40\n    elseif lvl >= 75 then\n        shieldMasteryPower = 30\n    elseif lvl >= 50 then\n        shieldMasteryPower = 20\n    elseif lvl >= 25 then\n        shieldMasteryPower = 10\n    end\n\n    mob:setMod(xi.mod.SHIELD_MASTERY_TP, shieldMasteryPower)\n    mob:setMod(xi.mod.SHIELDBLOCKRATE, 35)\n    mob:addMod(xi.mod.UFASTCAST, 50)\n    mob:addMod(xi.mod.DMG, -1000) -- Damage Taken -10%\n    mob:addMod(xi.mod.ENMITY, 25)\n    mob:addMod(xi.mod.HPP, 10)\n\n    -- Founders gear mods: August gets all effects from founders gear\n    -- see xi.trust.modGrowthVal in trust.lua for current curve value\n    mob:addMod(xi.mod.MDEF, xi.trust.modGrowthValMax(mob, 12))            -- Founders gear: MDEF + 12\n    mob:addMod(xi.mod.SPELLINTERRUPT, xi.trust.modGrowthValMax(mob, 30))  -- Founders gear: SIRD +30\n    mob:addMod(xi.mod.HASTE_GEAR, xi.trust.modGrowthValMax(mob, 22))      -- Founders gear: Gear Haste +22\n    mob:addMod(xi.mod.ACC, xi.trust.modGrowthValMax(mob, 60))             -- Founders gear: ACC + 60\n    mob:addMod(xi.mod.ATT, xi.trust.modGrowthValMax(mob, 60))             -- Founders gear: ATT +60\n    mob:addMod(xi.mod.MACC, xi.trust.modGrowthValMax(mob, 60))            -- Founders gear: MACC + 60\n    mob:addMod(xi.mod.EVA, xi.trust.modGrowthValMax(mob, 183))            -- Founders gear: EVA + 183\n    mob:addMod(xi.mod.MEVA, xi.trust.modGrowthValMax(mob, 299))           -- Founders gear: MEVA + 299\n    mob:addMod(xi.mod.MATT, xi.trust.modGrowthValMax(mob, 60))            -- Founders gear: MATT + 60\n    -- there is a few more, but these make the most sense for now.\n\n    mob:setAnimationSub(0) -- this is probably not needed but its here because August's daybreak status is tested against it.\n\n    -- mob:addImmunity(xi.immunity.TERROR) -- this is wrong but we currently have no TERRORRES mod and no way to use one\n\n    mob:addListener('COMBAT_TICK', 'AUGUST_CTICK', function(mobArg)\n        local daybreakRecast  = 180 -- 3 minutes\n        local daybreakEndTime = mobArg:getLocalVar('DaybreakEndTime')\n        local daybreakUsed    = mobArg:getLocalVar('DaybreakUsed')\n        local hppLow          = mobArg:getHPP() <= 66\n        local now             = GetSystemTime()\n        if\n            mobArg:getMainLvl() >= 51 and\n            mobArg:getAnimationSub() == 0 and\n            (daybreakEndTime == 0 or now >= daybreakEndTime + daybreakRecast) and\n            hppLow and\n            daybreakUsed ~= 1\n        then\n            mobArg:useMobAbility(xi.mobSkill.DAYBREAK_TRUST)\n            daybreakUsed = 1\n        end\n    end)\n\n    if lvl >= 10 then\n        mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\n    end\n\n    if lvl >= 30 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SENTINEL }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SENTINEL })\n    end\n\n    if lvl >= 95 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.PALISADE }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PALISADE })\n    end\n\n    if lvl >= 75 then\n        -- Only uses Divine Emblen and Holy when daybreak active (subAnimation 5)\n        mob:addGambit(ai.t.SELF, { { ai.c.SUB_ANIMATION, 5 }, { ai.c.NOT_STATUS, xi.effect.DIVINE_EMBLEM }, }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.DIVINE_EMBLEM })\n    end\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.FLASH    }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FLASH      })\n    mob:addGambit(ai.t.SELF,   { ai.c.HPP_LT,     75                 }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.CURE })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.REPRISAL }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.REPRISAL   })\n    mob:addGambit(ai.t.PARTY,  { ai.c.HPP_LT,     50                 }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.CURE })\n    mob:addGambit(ai.t.PARTY,  { ai.c.STATUS,     xi.effect.SLEEP_I  }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE       })\n\n    mob:addGambit(ai.t.TRIGGER_SELF_ACTION_TARGET, {\n        { ai.c.SUB_ANIMATION, 5 },\n        { ai.c.STATUS, xi.effect.DIVINE_EMBLEM }, }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.HOLY })\n\n    mob:setMobSkillAttack(1197)\n\n    mob:setTrustTPSkillSettings(ai.tp.OPENER, ai.s.SPECIAL_AUGUST)\n\n    mob:addListener('WEAPONSKILL_USE', 'AUGUST_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action)\n        if skill:getID() == xi.mobSkill.DAYBREAK_TRUST then -- Daybreak\n            mob:timer(2000, function()\n                mob:entityAnimationPacket('ids1') -- Wings on\n            end)\n        elseif skill:getID() == xi.mobSkill.NO_QUARTER_TRUST then -- No Quarter\n            -- Come! Show me your finest form!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n            mobArg:setLocalVar('DaybreakUsed', 0)\n            mob:timer(1000, function()\n                mob:entityAnimationPacket('ids2') -- Wings off\n            end)\n        end\n    end)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ayame.lua"]={["Path"]="scripts/actions/spells/trust/ayame.lua",["SHA256"]="380abc01ccf41594b8d79e2e4dde68c029eefdc84c3bb52d3e5fb72cb8ef2c1f",["Text"]="-----------------------------------\n-- Trust: Ayame\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.AYAME_UC)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.NAJI] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.GILGAMESH] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.HASSO }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.HASSO })\n\n    mob:addGambit(ai.t.SELF, { ai.c.HAS_TOP_ENMITY, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.THIRD_EYE })\n\n    mob:addGambit(ai.t.SELF, { ai.c.TP_LT, 1000 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.MEDITATE })\n\n    mob:setTrustTPSkillSettings(ai.tp.OPENER, ai.s.SPECIAL_AYAME)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ayame_uc.lua"]={["Path"]="scripts/actions/spells/trust/ayame_uc.lua",["SHA256"]="cc4ca25f3c00f68d1004d4d3cfb042884e23b7f21fc1f844b61e76e24ffa7206",["Text"]="-----------------------------------\n-- Trust: Ayame UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.AYAME)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/babban.lua"]={["Path"]="scripts/actions/spells/trust/babban.lua",["SHA256"]="d4d1000476b2901492143e01679f2cdaa8ae7f120a445e50586fb1265b8dab9b",["Text"]="-----------------------------------\n-- Trust: Babban\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nlocal isWearingMandragoraGear = function(player)\n    local wearingHead = player:getEquipID(xi.slot.HEAD) == 26705 or player:getEquipID(xi.slot.HEAD) == 26706 -- Mandragora Masque or Masque + 1\n    local wearingBody = player:getEquipID(xi.slot.BODY) == 27854 or player:getEquipID(xi.slot.BODY) == 27855 -- Mandragora Suit or Suit + 1\n    return wearingHead and wearingBody\nend\n\nspellObject.onMobSpawn = function(mob)\n    local master = mob:getMaster()\n    if isWearingMandragoraGear(master) then\n        xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n    end\nend\n\nspellObject.onMobDespawn = function(mob)\n    local master = mob:getMaster()\n    if isWearingMandragoraGear(master) then\n        xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\n    end\nend\n\nspellObject.onMobDeath = function(mob)\n    local master = mob:getMaster()\n    if isWearingMandragoraGear(master) then\n        xi.trust.message(mob, xi.trust.messageOffset.DEATH)\n    end\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/balamor.lua"]={["Path"]="scripts/actions/spells/trust/balamor.lua",["SHA256"]="47d8898e0d85259febce9e0d914bf4284711d1fc6200ba4be31db655f1c39e79",["Text"]="-----------------------------------\n-- Trust: Balamor\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/brygid.lua"]={["Path"]="scripts/actions/spells/trust/brygid.lua",["SHA256"]="fb217a6b741f40f6a02e7b752d858bf6560fbc1b1a79a89df7c0face51047b0b",["Text"]="-----------------------------------\n-- Trust: Brygid\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NON_COMBAT)\n\n    mob:addMod(xi.mod.AURA_SIZE, 600) -- Trust have a 12 yalm aura 6 base + 6 from mod\n\n    local effectParams =\n    {\n        power = 6,\n        origin = mob,\n        tick = 3,\n        subType = xi.effect.TRUST_AURA_CHR,\n        subPower = mob:getMainLvl(),\n        subIcon = xi.effect.GEO_CHR_BOOST,\n        tier = xi.auraTarget.ALLIES,\n        flag = xi.effectFlag.AURA\n    }\n\n    mob:addStatusEffect(xi.effect.COLURE_ACTIVE, effectParams)\n\n    mob:addGambit(ai.t.SELF, { { ai.c.TIMER, 5 }, { ai.c.RANDOM, 45 } }, { ai.r.ANIM_STRING, ai.s.RANDOM_ANIMATION, 3 })\n\n    mob:setAutoAttackEnabled(false)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/chacharoon.lua"]={["Path"]="scripts/actions/spells/trust/chacharoon.lua",["SHA256"]="83dc780b1509d9f0b84ba18e9d12dbafda5e4a200216caef588af820b28c1fb1",["Text"]="-----------------------------------\n-- Trust: Chacharoon\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/cherukiki.lua"]={["Path"]="scripts/actions/spells/trust/cherukiki.lua",["SHA256"]="ecc94268f8e5da75e64ea143ab151d80dc54b05dd2ef5680c9777e4eb67e19ad",["Text"]="-----------------------------------\n-- Trust: Cherukiki\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.MAKKI_CHEBUKKI] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.KUKKI_CHEBUKKI] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.PRISHE] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.TENZEN] = xi.trust.messageOffset.TEAMWORK_4,\n    })\n\n    -- TODO: Research numerous emotes\n    -- TODO: Verify amount of Regen potency, Regen effect\n    -- TODO: Is supposed to path erratically during battle\n    -- TODO: Meteor casting with siblings\n    -- TODO: Any intelligence with casting Silence on mobs?\n\n    mob:addGambit(ai.t.MASTER, { ai.c.NOT_STATUS, xi.effect.REGEN }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.REGEN })\n    mob:addGambit(ai.t.MELEE, { ai.c.NOT_STATUS, xi.effect.REGEN }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.REGEN })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 25 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spellFamily.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECTRA })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.SHELL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SHELLRA })\n\n    mob:addGambit(ai.t.MASTER, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.HASTE })\n    mob:addGambit(ai.t.MELEE, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.HASTE })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PARALYZE }, 60)\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.SLOW }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SLOW }, 60)\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENCE }, 60)\n\n    -- BGwiki states 5/tick regen.\n    mob:addMod(xi.mod.REGEN, 5)\n\n    mob:setAutoAttackEnabled(false)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.MID_RANGE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/cid.lua"]={["Path"]="scripts/actions/spells/trust/cid.lua",["SHA256"]="1202ec9e8a2cac28fe274745ab8b6eb2e5e9ab7f645f07f9760ccb2583b9e334",["Text"]="-----------------------------------\n-- Trust: Cid\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/cornelia.lua"]={["Path"]="scripts/actions/spells/trust/cornelia.lua",["SHA256"]="6eedd1d1976160737335fec403d27a17ec63af853da306b96c637b27bc3c1a62",["Text"]="-----------------------------------\n-- Trust: Cornelia\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NON_COMBAT)\n\n    mob:addMod(xi.mod.AURA_SIZE, 600) -- Trust have a 12 yalm aura 6 base + 6 from mod\n\n    local effectParams =\n    {\n        power = 6,\n        origin = mob,\n        tick = 3,\n        subType = xi.effect.TRUST_AURA_HASTE,\n        subPower = mob:getMainLvl(),\n        subIcon = xi.effect.GEO_HASTE,\n        tier = xi.auraTarget.ALLIES,\n        flag = xi.effectFlag.AURA\n    }\n\n    mob:addStatusEffect(xi.effect.COLURE_ACTIVE, effectParams)\n\n    mob:addGambit(ai.t.SELF, { { ai.c.TIMER, 5 }, { ai.c.RANDOM, 45 } }, { ai.r.ANIM_STRING, ai.s.RANDOM_ANIMATION, 4 })\n\n    mob:setAutoAttackEnabled(false)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/curilla.lua"]={["Path"]="scripts/actions/spells/trust/curilla.lua",["SHA256"]="07a196b5208eaa3ac8208bd6d506a8882c3659364c60f483749ac7da43f28aef",["Text"]="-----------------------------------\n-- Trust: Curilla\n-- Possesses MP+30%, Guardian (Sentinel enmity loss -95%), Sentinel Recast merited (-50 sec), Cure Potency Bonus+25%, and Cure Casting Time Down.\n-- Does not use Provoke, but will use Flash. This leads to poor hate control.\n-- Uses TP randomly and does not try to skillchain.\n-- Cures players and trusts in yellow (<75%) HP.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.TRION] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.RAINEMARD] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.RAHAL] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.HALVER] = xi.trust.messageOffset.TEAMWORK_4,\n    })\n\n    mob:addListener('ABILITY_USE', 'SENTINEL_USE' .. 'ABILITY', function(mobArg, target, skill, action)\n        if skill:getID() == xi.jobAbility.SENTINEL then\n            skill:setRecast(skill:getRecast() - 50) -- Sentinel Recast merited (-50 sec)\n        end\n    end)\n\n    mob:addListener('COMBAT_TICK', 'CURILLA_CTICK', function(mobArg)\n        local effect = mob:getStatusEffect(xi.effect.SENTINEL)\n        if effect and effect:getSubPower() ~= 95 then\n            effect:setSubPower(95) -- Guardian (Sentinel enmity loss -95%)\n        end\n    end)\n\n    local lvl = mob:getMainLvl()\n    local shieldMasteryPower = 0\n\n    if lvl >= 96 then\n        shieldMasteryPower = 40\n    elseif lvl >= 75 then\n        shieldMasteryPower = 30\n    elseif lvl >= 50 then\n        shieldMasteryPower = 20\n    elseif lvl >= 25 then\n        shieldMasteryPower = 10\n    end\n\n    mob:setMod(xi.mod.SHIELD_MASTERY_TP, shieldMasteryPower)\n    mob:addMod(xi.mod.ENHANCES_GUARDIAN, 30)\n    mob:setMod(xi.mod.SHIELDBLOCKRATE, 25)\n    mob:addMod(xi.mod.CURE_CAST_TIME, 50)\n    mob:addMod(xi.mod.CURE_POTENCY, 25)\n    mob:addMod(xi.mod.ENMITY, 15)\n    mob:addMod(xi.mod.DMG, -500) -- Damage Taken -5%\n    mob:addMod(xi.mod.HPP, 10)\n    mob:addMod(xi.mod.MPP, 30)\n\n    if lvl >= 30 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SENTINEL }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SENTINEL })\n    end\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.FLASH }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FLASH      })\n    mob:addGambit(ai.t.PARTY,  { ai.c.HPP_LT,     75              }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.CURE })\n\n    mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/d_shantotto.lua"]={["Path"]="scripts/actions/spells/trust/d_shantotto.lua",["SHA256"]="600e09f4fb80c2d46838cafbd11de9371ee43e04b5bba249074b20db82404bb0",["Text"]="-----------------------------------\n-- Trust: D Shantotto\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/darrcuiln.lua"]={["Path"]="scripts/actions/spells/trust/darrcuiln.lua",["SHA256"]="5b3a4e71609b340dcc9d9df418c8348478ef3606e2e7283d5fe2ef097aef20d0",["Text"]="-----------------------------------\n-- Trust: Darrcuiln\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/elivira.lua"]={["Path"]="scripts/actions/spells/trust/elivira.lua",["SHA256"]="171c7a0e023a148b08bd8189a915520d684bd7496c34e7353d948050b074860a",["Text"]="-----------------------------------\n-- Trust: Elivira\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/excenmille.lua"]={["Path"]="scripts/actions/spells/trust/excenmille.lua",["SHA256"]="e6ca79ae03c31d820282234211d86786580bbee5fc2cab33fb95325f0b795008",["Text"]="-----------------------------------\n-- Trust: Excenmille\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.EXCENMILLE_S)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local sandoriaFirstTrust = caster:getCharVar('SandoriaFirstTrust')\n    local zone = caster:getZoneID()\n\n    if\n        sandoriaFirstTrust == 1 and\n        (zone == xi.zone.WEST_RONFAURE or zone == xi.zone.EAST_RONFAURE)\n    then\n        caster:setCharVar('SandoriaFirstTrust', 2)\n    end\n\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.RAHAL] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SENTINEL }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SENTINEL })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.FLASH }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FLASH })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addMod(xi.mod.STORETP, 25)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/excenmille_s.lua"]={["Path"]="scripts/actions/spells/trust/excenmille_s.lua",["SHA256"]="1b1d00d1618e42c5db34ee91f1c9114545b587146f9449b93dda9ad7f1d4ac06",["Text"]="-----------------------------------\n-- Trust: Excenmille S\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.EXCENMILLE)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/fablinix.lua"]={["Path"]="scripts/actions/spells/trust/fablinix.lua",["SHA256"]="abd2d80ba6e9387eb9114a54610effeb8aa6bfd072c943befc7af62f085c64ee",["Text"]="-----------------------------------\n-- Trust: Fablinix\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.MOOGLE] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_WS, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_MS, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_JA, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n    mob:addGambit(ai.t.TARGET, { ai.c.CASTING_MA, 0 }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STUN })\n\n    mob:addGambit(ai.t.TANK, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 50 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.ENWATER }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ENWATER })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.RANDOM, 50 }, { ai.r.RATTACK, 0, 0 }, 30) -- TODO: Verify rate of ranged attacks\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.HIGHEST, 1500)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ferreous_coffin.lua"]={["Path"]="scripts/actions/spells/trust/ferreous_coffin.lua",["SHA256"]="3e695a0f8eb6c08d64c9b7703d3fe06620f24b2673c8bb706c73344b6bba3e79",["Text"]="-----------------------------------\n-- Trust: Ferreous Coffin\n-- Auto Refresh II (Cleric's Bliaut +2). HP-10%, MP+35%\n-- Will only cast Raise III on KO party members in casting range.\n-- Will only cast status ailment removal spells on the player with the highest enmity.\n-- Has a high Cursna success rate (only casts on the highest threat player) Official note\n-- Ferreous Coffin only uses Randgrith and benefits from relic aftermath (acc +20).\n-- Will use TP as soon as he gets it, so he is good at maintaining enemy Evasion Down and initiating Light skillchains.\n-- Casts Haste on party members regardless of job.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    -- HPP/MPP mods migrated to sql/mob_pool_mods\n    mob:addMod(xi.mod.REFRESH, 2)\n    mob:addMod(xi.mod.ENHANCES_CURSNA, 20)\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLOW }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.HASTE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PARALYNA })\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.STATUS, xi.effect.BLINDNESS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.BLINDNA })\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENA })\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.STATUS, xi.effect.PETRIFICATION }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONA })\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.STATUS, xi.effect.DISEASE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.VIRUNA })\n\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.STATUS, xi.effect.CURSE_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.STATUS, xi.effect.CURSE_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.STATUS, xi.effect.BANE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.STATUS, xi.effect.DOOM }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n\n    mob:addGambit(ai.t.PARTY_DEAD, { ai.c.ALWAYS, 0 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.RAISE })\n\n    mob:addListener('WEAPONSKILL_USE', 'FERREOUS_COFFIN_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == xi.mobSkill.RANDGRITH_1 then\n            if math.randomInt(1, 100) <= 66 then\n                xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1) -- Return to the dust whence you came! Randgrith!!!\n            end\n\n            mob:addStatusEffect(xi.effect.ACCURACY_BOOST, { power = 20, duration = 20, origin = mob }) -- Cheat in Relic AM ACC\n            -- TODO: Expand Relic (Mjollnir) Handling (Occ. Double Damage, etc)\n        end\n    end)\n\n    mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"}};
